1	import "server-only";
2	
3	import { cache } from "react";
4	import { redirect } from "next/navigation";
5	import { createClient } from "@/lib/supabase/server";
6	
7	export type Role = "member" | "moderator" | "admin";
8	
9	export type SessionUser = {
10	  id: string;
11	  email: string | null;
12	  role: Role;
13	  username: string | null;
14	  displayName: string | null;
15	  avatarUrl: string | null;
16	  isBanned: boolean;
17	};
18	
19	/**
20	 * Data Access Layer. Following the Next.js 16 auth guidance, authorization
21	 * checks live here (close to the data) rather than in a layout or proxy.
22	 * `cache` memoizes the lookup for a single render pass.
23	 */
24	export const getSessionUser = cache(async (): Promise<SessionUser | null> => {
25	  const supabase = await createClient();
26	  const {
27	    data: { user },
28	  } = await supabase.auth.getUser();
29	  if (!user) return null;
30	
31	  const { data: profile } = await supabase
32	    .from("profiles")
33	    .select("role, username, display_name, avatar_url, is_banned")
34	    .eq("id", user.id)
35	    .single();
36	
37	  return {
38	    id: user.id,
39	    email: user.email ?? null,
40	    role: (profile?.role as Role) ?? "member",
41	    username: profile?.username ?? null,
42	    displayName: profile?.display_name ?? null,
43	    avatarUrl: profile?.avatar_url ?? null,
44	    isBanned: profile?.is_banned ?? false,
45	  };
46	});
47	
48	/** Require an authenticated, non-banned user or redirect to /login. */
49	export async function requireUser(): Promise<SessionUser> {
50	  const user = await getSessionUser();
51	  if (!user) redirect("/login");
52	  if (user.isBanned) redirect("/banned");
53	  return user;
54	}
55	
56	/** Require a moderator or admin, or send unauthorized users home. */
57	export async function requireAdmin(): Promise<SessionUser> {
58	  const user = await requireUser();
59	  if (user.role !== "admin" && user.role !== "moderator") redirect("/");
60	  return user;
61	}
