1	import { createServerClient } from "@supabase/ssr";
2	import { cookies } from "next/headers";
3	
4	/**
5	 * Supabase client for Server Components, Server Actions, and Route Handlers.
6	 * Reads the user's session from cookies and enforces RLS as the authed user.
7	 * `cookies()` is async in Next.js 16.
8	 */
9	export async function createClient() {
10	  const cookieStore = await cookies();
11	
12	  return createServerClient(
13	    process.env.NEXT_PUBLIC_SUPABASE_URL!,
14	    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
15	    {
16	      cookies: {
17	        getAll() {
18	          return cookieStore.getAll();
19	        },
20	        setAll(cookiesToSet) {
21	          try {
22	            cookiesToSet.forEach(({ name, value, options }) =>
23	              cookieStore.set(name, value, options),
24	            );
25	          } catch {
26	            // `setAll` was called from a Server Component. This can be ignored
27	            // when the session refresh runs in proxy.ts (which it does).
28	          }
29	        },
30	      },
31	    },
32	  );
33	}
