1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { createClient } from "@/lib/supabase/server";
5	import { requireUser } from "@/lib/auth/dal";
6	import { profileSchema } from "@/lib/validation/auth";
7	
8	export type ProfileState = {
9	  ok?: boolean;
10	  message?: string;
11	  error?: string;
12	};
13	
14	/** Update the current user's own profile. RLS also restricts this to self. */
15	export async function updateProfile(
16	  _prev: ProfileState,
17	  formData: FormData,
18	): Promise<ProfileState> {
19	  const user = await requireUser();
20	
21	  const parsed = profileSchema.safeParse({
22	    display_name: formData.get("display_name"),
23	    bio: formData.get("bio"),
24	    website_url: formData.get("website_url"),
25	    x_url: formData.get("x_url"),
26	    linkedin_url: formData.get("linkedin_url"),
27	  });
28	
29	  if (!parsed.success) {
30	    return { error: parsed.error.issues[0]?.message ?? "Invalid input." };
31	  }
32	
33	  // Normalize empty strings to null so we don't store blanks.
34	  const patch = Object.fromEntries(
35	    Object.entries(parsed.data).map(([k, v]) => [k, v === "" ? null : v]),
36	  );
37	
38	  const supabase = await createClient();
39	  const { error } = await supabase
40	    .from("profiles")
41	    .update(patch)
42	    .eq("id", user.id);
43	
44	  if (error) return { error: error.message };
45	
46	  revalidatePath("/settings/profile");
47	  if (user.username) revalidatePath(`/u/${user.username}`);
48	  return { ok: true, message: "Profile saved." };
49	}
