1	import Link from "next/link";
2	import type { ComponentProps, ReactNode } from "react";
3	
4	type Variant = "blue" | "lime" | "purple" | "ink";
5	type Size = "md" | "lg";
6	
7	const VARIANTS: Record<Variant, string> = {
8	  blue: "bg-brand-blue text-white",
9	  lime: "bg-brand-lime text-brand-ink",
10	  purple: "bg-brand-purple text-white",
11	  ink: "bg-brand-ink text-white",
12	};
13	
14	const SIZES: Record<Size, string> = {
15	  md: "px-6 py-3 text-lg",
16	  lg: "px-8 py-4 text-xl sm:text-2xl",
17	};
18	
19	const base =
20	  "focus-comic inline-flex items-center justify-center gap-2 rounded-[var(--radius-comic)] border-ink font-display uppercase tracking-wide shadow-comic transition-transform duration-100 hover:-translate-x-0.5 hover:-translate-y-0.5 hover:shadow-comic-lg active:translate-x-0.5 active:translate-y-0.5 active:shadow-comic-sm";
21	
22	/** A chunky comic-styled button. Renders an <a> when `href` is set, else a <button>. */
23	export function ComicButton({
24	  children,
25	  variant = "blue",
26	  size = "md",
27	  className = "",
28	  href,
29	  ...props
30	}: {
31	  children: ReactNode;
32	  variant?: Variant;
33	  size?: Size;
34	  className?: string;
35	  href?: string;
36	} & Omit<ComponentProps<"button">, "className">) {
37	  const classes = `${base} ${SIZES[size]} ${VARIANTS[variant]} ${className}`;
38	
39	  if (href) {
40	    return (
41	      <Link href={href} className={classes}>
42	        {children}
43	      </Link>
44	    );
45	  }
46	
47	  return (
48	    <button className={classes} {...props}>
49	      {children}
50	    </button>
51	  );
52	}
