1	"use server";
2	
3	import { headers } from "next/headers";
4	import { redirect } from "next/navigation";
5	import { createClient } from "@/lib/supabase/server";
6	import { emailSchema } from "@/lib/validation/auth";
7	
8	export type AuthState = {
9	  ok?: boolean;
10	  message?: string;
11	  error?: string;
12	};
13	
14	/** Resolve the site origin for auth redirects (env first, then request host). */
15	async function getOrigin() {
16	  const envUrl = process.env.NEXT_PUBLIC_SITE_URL;
17	  if (envUrl) return envUrl.replace(/\/$/, "");
18	  const h = await headers();
19	  const host = h.get("x-forwarded-host") ?? h.get("host");
20	  const proto = h.get("x-forwarded-proto") ?? "https";
21	  return `${proto}://${host}`;
22	}
23	
24	/** Email one-time code / magic link sign-in (delivered via Resend SMTP). */
25	export async function signInWithOtp(
26	  _prev: AuthState,
27	  formData: FormData,
28	): Promise<AuthState> {
29	  const parsed = emailSchema.safeParse({ email: formData.get("email") });
30	  if (!parsed.success) {
31	    return { error: parsed.error.issues[0]?.message ?? "Invalid email." };
32	  }
33	
34	  const supabase = await createClient();
35	  const origin = await getOrigin();
36	  const { error } = await supabase.auth.signInWithOtp({
37	    email: parsed.data.email,
38	    options: {
39	      shouldCreateUser: true,
40	      emailRedirectTo: `${origin}/auth/confirm`,
41	    },
42	  });
43	
44	  if (error) return { error: error.message };
45	  return {
46	    ok: true,
47	    message: `We sent a sign-in link to ${parsed.data.email}. Check your inbox.`,
48	  };
49	}
50	
51	/** Start the GitHub OAuth flow, then redirect the browser to GitHub. */
52	export async function signInWithGithub() {
53	  const supabase = await createClient();
54	  const origin = await getOrigin();
55	  const { data, error } = await supabase.auth.signInWithOAuth({
56	    provider: "github",
57	    options: {
58	      redirectTo: `${origin}/auth/callback`,
59	      scopes: "read:user user:email",
60	    },
61	  });
62	
63	  if (error) redirect(`/login?error=${encodeURIComponent(error.message)}`);
64	  if (data.url) redirect(data.url);
65	}
66	
67	export async function signOut() {
68	  const supabase = await createClient();
69	  await supabase.auth.signOut();
70	  redirect("/");
71	}
