1	import { NextResponse, type NextRequest } from "next/server";
2	import { createClient } from "@/lib/supabase/server";
3	
4	/**
5	 * OAuth callback (GitHub). Exchanges the `code` for a session, then redirects
6	 * to `next` (defaults to the dashboard).
7	 */
8	export async function GET(request: NextRequest) {
9	  const { searchParams, origin } = new URL(request.url);
10	  const code = searchParams.get("code");
11	  const next = searchParams.get("next") ?? "/dashboard";
12	  const error = searchParams.get("error_description") ?? searchParams.get("error");
13	
14	  if (error) {
15	    return NextResponse.redirect(
16	      `${origin}/login?error=${encodeURIComponent(error)}`,
17	    );
18	  }
19	
20	  if (code) {
21	    const supabase = await createClient();
22	    const { error: exchangeError } =
23	      await supabase.auth.exchangeCodeForSession(code);
24	    if (!exchangeError) {
25	      // Respect proxied host in production (Vercel).
26	      const forwardedHost = request.headers.get("x-forwarded-host");
27	      const isLocal = process.env.NODE_ENV === "development";
28	      const base = isLocal || !forwardedHost ? origin : `https://${forwardedHost}`;
29	      return NextResponse.redirect(`${base}${next}`);
30	    }
31	    return NextResponse.redirect(
32	      `${origin}/login?error=${encodeURIComponent(exchangeError.message)}`,
33	    );
34	  }
35	
36	  return NextResponse.redirect(`${origin}/login?error=missing_code`);
37	}
