import * as z from "zod";

export const eventAccentEnum = z.enum(["blue", "lime", "purple"]);
export const eventStatusEnum = z.enum(["draft", "published", "cancelled"]);
export const rsvpStatusEnum = z.enum(["going", "interested"]);

// Lowercase, hyphen-separated slug — the permanent URL segment for an event.
const slugRegex = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

export const eventSchema = z.object({
  title: z
    .string()
    .trim()
    .min(3, { error: "Give the event a title." })
    .max(140, { error: "Keep the title under 140 characters." }),
  slug: z
    .string()
    .trim()
    .toLowerCase()
    .min(3, { error: "Slug must be at least 3 characters." })
    .max(80)
    .regex(slugRegex, {
      error: "Slug: lowercase letters, numbers, and hyphens only.",
    }),
  summary: z
    .string()
    .trim()
    .max(200, { error: "Summaries are limited to 200 characters." })
    .optional()
    .or(z.literal("")),
  description: z
    .string()
    .trim()
    .max(5000, { error: "Descriptions are limited to 5000 characters." })
    .optional()
    .or(z.literal("")),
  // datetime-local strings, e.g. "2026-10-09T13:00". Converted to UTC in the action.
  starts_at: z.string().min(1, { error: "Pick a start date and time." }),
  ends_at: z.string().optional().or(z.literal("")),
  timezone: z.string().trim().max(64).optional().or(z.literal("")),
  location: z.string().trim().max(200).optional().or(z.literal("")),
  host: z.string().trim().max(80).optional().or(z.literal("")),
  accent: eventAccentEnum,
  status: eventStatusEnum,
});

export type EventInput = z.infer<typeof eventSchema>;

// Event date formatting.
//
// DECISION (see docs/DECISIONS.md): event times are stored as the admin's
// wall-clock interpreted as UTC and are ALWAYS displayed in UTC, so the time
// shown equals exactly what the admin entered. The timezone label communicates
// the intended zone. Proper multi-timezone conversion is deferred (needs a TZ
// library); for a single-community listing this is predictable and bug-free.

const TZ_LABELS: Record<string, string> = {
  "America/New_York": "ET",
  "America/Chicago": "CT",
  "America/Denver": "MT",
  "America/Los_Angeles": "PT",
  "Europe/London": "GMT",
  UTC: "UTC",
};

export function tzLabel(tz?: string | null): string {
  if (!tz) return "";
  return TZ_LABELS[tz] ?? tz;
}

/** Compact parts for the comic date plate on event cards. */
export function formatDateParts(iso: string) {
  const date = new Date(iso);
  const part = (opts: Intl.DateTimeFormatOptions) =>
    new Intl.DateTimeFormat("en-US", { ...opts, timeZone: "UTC" }).format(date);
  return {
    month: part({ month: "short" }).toUpperCase(),
    day: part({ day: "2-digit" }),
    weekday: part({ weekday: "short" }),
    time: part({ hour: "numeric", minute: "2-digit" }),
  };
}

/** Full human date, e.g. "Thursday, October 9, 2026". */
export function formatFullDate(iso: string) {
  return new Intl.DateTimeFormat("en-US", {
    weekday: "long",
    month: "long",
    day: "numeric",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(iso));
}

/** Time only, e.g. "1:00 PM". */
export function formatTime(iso: string) {
  return new Intl.DateTimeFormat("en-US", {
    hour: "numeric",
    minute: "2-digit",
    timeZone: "UTC",
  }).format(new Date(iso));
}

/** Convert a stored UTC ISO timestamp back to a datetime-local input value. */
export function toDatetimeLocalValue(iso: string): string {
  // Stored as UTC wall-clock; slice to "YYYY-MM-DDTHH:mm".
  return iso.slice(0, 16);
}

import "server-only";

import { createClient } from "@/lib/supabase/server";

export type EventAccent = "blue" | "lime" | "purple";
export type EventStatus = "draft" | "published" | "cancelled";
export type RsvpStatus = "going" | "interested";

export type EventRow = {
  id: string;
  slug: string;
  title: string;
  summary: string | null;
  description: string | null;
  starts_at: string;
  ends_at: string | null;
  timezone: string;
  location: string | null;
  is_virtual: boolean;
  host: string | null;
  accent: EventAccent;
  status: EventStatus;
  is_live: boolean;
  stream_embed_url: string | null;
  created_by: string | null;
  created_at: string;
  updated_at: string;
};

const EVENT_COLUMNS =
  "id, slug, title, summary, description, starts_at, ends_at, timezone, location, is_virtual, host, accent, status, is_live, stream_embed_url, created_by, created_at, updated_at";

/** Published events, upcoming (ascending) or past (descending). RLS-safe. */
export async function listPublishedEvents(opts?: {
  when?: "upcoming" | "past";
  limit?: number;
}): Promise<EventRow[]> {
  const supabase = await createClient();
  const nowIso = new Date().toISOString();
  const when = opts?.when ?? "upcoming";

  let query = supabase
    .from("events")
    .select(EVENT_COLUMNS)
    .eq("status", "published");

  query =
    when === "upcoming"
      ? query.gte("starts_at", nowIso).order("starts_at", { ascending: true })
      : query.lt("starts_at", nowIso).order("starts_at", { ascending: false });

  if (opts?.limit) query = query.limit(opts.limit);

  const { data, error } = await query;
  if (error) throw error;
  return (data ?? []) as EventRow[];
}

/** A single event by its permanent slug. Visibility follows RLS. */
export async function getEventBySlug(slug: string): Promise<EventRow | null> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("events")
    .select(EVENT_COLUMNS)
    .eq("slug", slug)
    .maybeSingle();
  if (error) throw error;
  return (data as EventRow) ?? null;
}

/** A single event by id (admin edit). Visibility follows RLS. */
export async function getEventById(id: string): Promise<EventRow | null> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("events")
    .select(EVENT_COLUMNS)
    .eq("id", id)
    .maybeSingle();
  if (error) throw error;
  return (data as EventRow) ?? null;
}

/** All events including drafts — admin management view (RLS gates to admins). */
export async function listAllEventsForAdmin(): Promise<EventRow[]> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("events")
    .select(EVENT_COLUMNS)
    .order("starts_at", { ascending: false });
  if (error) throw error;
  return (data ?? []) as EventRow[];
}

export type RsvpSummary = { going: number; interested: number };

export async function getRsvpSummary(eventId: string): Promise<RsvpSummary> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("rsvps")
    .select("status")
    .eq("event_id", eventId);
  if (error) throw error;

  const summary: RsvpSummary = { going: 0, interested: 0 };
  for (const row of (data ?? []) as { status: RsvpStatus }[]) {
    summary[row.status] += 1;
  }
  return summary;
}

export type Attendee = {
  user_id: string;
  status: RsvpStatus;
  username: string | null;
  display_name: string | null;
  avatar_url: string | null;
};

type RawAttendee = {
  user_id: string;
  status: RsvpStatus;
  profiles: {
    username: string | null;
    display_name: string | null;
    avatar_url: string | null;
  } | null;
};

/** Members who RSVP'd, newest-joined last. Powers the "who's going" list. */
export async function getAttendees(
  eventId: string,
  opts?: { status?: RsvpStatus; limit?: number },
): Promise<Attendee[]> {
  const supabase = await createClient();
  let query = supabase
    .from("rsvps")
    .select("user_id, status, profiles ( username, display_name, avatar_url )")
    .eq("event_id", eventId)
    .order("created_at", { ascending: true });

  if (opts?.status) query = query.eq("status", opts.status);
  if (opts?.limit) query = query.limit(opts.limit);

  const { data, error } = await query;
  if (error) throw error;

  return ((data ?? []) as unknown as RawAttendee[]).map((row) => ({
    user_id: row.user_id,
    status: row.status,
    username: row.profiles?.username ?? null,
    display_name: row.profiles?.display_name ?? null,
    avatar_url: row.profiles?.avatar_url ?? null,
  }));
}

/** The current user's RSVP status for an event, or null. */
export async function getUserRsvp(
  eventId: string,
  userId: string,
): Promise<RsvpStatus | null> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("rsvps")
    .select("status")
    .eq("event_id", eventId)
    .eq("user_id", userId)
    .maybeSingle();
  if (error) throw error;
  return (data?.status as RsvpStatus) ?? null;
}

"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { requireAdmin, requireUser } from "@/lib/auth/dal";
import { eventSchema, rsvpStatusEnum } from "@/lib/validation/events";

export type EventFormState = { error?: string };

/** Interpret a datetime-local value ("YYYY-MM-DDTHH:mm") as UTC wall-clock. */
function toUtcIso(local: string): string | null {
  if (!local) return null;
  const date = new Date(`${local}Z`);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

function nullIfEmpty(value: string | undefined | null): string | null {
  return value && value.trim() !== "" ? value : null;
}

function parseEventForm(formData: FormData) {
  return eventSchema.safeParse({
    title: formData.get("title"),
    slug: formData.get("slug"),
    summary: formData.get("summary"),
    description: formData.get("description"),
    starts_at: formData.get("starts_at"),
    ends_at: formData.get("ends_at"),
    timezone: formData.get("timezone"),
    location: formData.get("location"),
    host: formData.get("host"),
    accent: formData.get("accent"),
    status: formData.get("status"),
  });
}

function eventRecordFrom(
  data: ReturnType<typeof eventSchema.parse>,
  formData: FormData,
) {
  const startIso = toUtcIso(data.starts_at);
  if (!startIso) return { error: "Invalid start date and time." as const };

  return {
    record: {
      title: data.title,
      slug: data.slug,
      summary: nullIfEmpty(data.summary),
      description: nullIfEmpty(data.description),
      starts_at: startIso,
      ends_at: data.ends_at ? toUtcIso(data.ends_at) : null,
      timezone: nullIfEmpty(data.timezone) ?? "America/New_York",
      location: nullIfEmpty(data.location),
      is_virtual: formData.get("is_virtual") === "on",
      host: nullIfEmpty(data.host),
      accent: data.accent,
      status: data.status,
    },
  };
}

export async function createEvent(
  _prev: EventFormState,
  formData: FormData,
): Promise<EventFormState> {
  const user = await requireAdmin();

  const parsed = parseEventForm(formData);
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Check the form." };
  }

  const built = eventRecordFrom(parsed.data, formData);
  if ("error" in built) return { error: built.error };

  const supabase = await createClient();
  const { error } = await supabase
    .from("events")
    .insert({ ...built.record, created_by: user.id });

  if (error) {
    if (error.code === "23505") return { error: "That slug is already taken." };
    return { error: error.message };
  }

  revalidatePath("/events");
  revalidatePath("/");
  revalidatePath("/admin/events");
  redirect("/admin/events");
}

export async function updateEvent(
  _prev: EventFormState,
  formData: FormData,
): Promise<EventFormState> {
  await requireAdmin();

  const id = String(formData.get("id") ?? "");
  if (!id) return { error: "Missing event id." };

  const parsed = parseEventForm(formData);
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Check the form." };
  }

  const built = eventRecordFrom(parsed.data, formData);
  if ("error" in built) return { error: built.error };

  const supabase = await createClient();
  const { error } = await supabase
    .from("events")
    .update(built.record)
    .eq("id", id);

  if (error) {
    if (error.code === "23505") return { error: "That slug is already taken." };
    return { error: error.message };
  }

  revalidatePath("/events");
  revalidatePath(`/events/${built.record.slug}`);
  revalidatePath("/");
  revalidatePath("/admin/events");
  redirect("/admin/events");
}

/** Create or update the current user's RSVP. Invoked from a logged-in control. */
export async function setRsvp(formData: FormData): Promise<void> {
  const user = await requireUser();
  const eventId = String(formData.get("event_id") ?? "");
  const slug = String(formData.get("slug") ?? "");
  const parsedStatus = rsvpStatusEnum.safeParse(formData.get("status"));
  if (!eventId || !parsedStatus.success) return;

  const supabase = await createClient();
  const { error } = await supabase
    .from("rsvps")
    .upsert(
      { event_id: eventId, user_id: user.id, status: parsedStatus.data },
      { onConflict: "event_id,user_id" },
    );
  if (error) throw error;

  if (slug) revalidatePath(`/events/${slug}`);
}

export async function cancelRsvp(formData: FormData): Promise<void> {
  const user = await requireUser();
  const eventId = String(formData.get("event_id") ?? "");
  const slug = String(formData.get("slug") ?? "");
  if (!eventId) return;

  const supabase = await createClient();
  const { error } = await supabase
    .from("rsvps")
    .delete()
    .eq("event_id", eventId)
    .eq("user_id", user.id);
  if (error) throw error;

  if (slug) revalidatePath(`/events/${slug}`);
}

import Link from "next/link";
import { Logo } from "@/components/brand/logo";
import { ComicButton } from "@/components/brand/comic-button";
import { getSessionUser } from "@/lib/auth/dal";

const NAV = [
  { href: "/events", label: "Events" },
  { href: "/discussions", label: "Discussions" },
  { href: "/showcase", label: "Showcase" },
];

/** Public site header for no-auth pages (events, profiles, …). */
export async function PublicHeader() {
  const user = await getSessionUser();

  return (
    <header className="sticky top-0 z-20 border-b-[3px] border-brand-ink bg-brand-cream/90 backdrop-blur supports-[backdrop-filter]:bg-brand-cream/75">
      <div className="mx-auto flex max-w-6xl items-center justify-between px-6 py-4">
        <Logo />
        <nav aria-label="Primary" className="hidden items-center gap-6 md:flex">
          {NAV.map((item) => (
            <Link
              key={item.href}
              href={item.href}
              className="focus-comic font-display text-lg uppercase tracking-wide text-brand-ink transition-colors hover:text-brand-blue"
            >
              {item.label}
            </Link>
          ))}
        </nav>
        {user ? (
          <ComicButton href="/dashboard" variant="lime">
            Dashboard
          </ComicButton>
        ) : (
          <ComicButton href="/login" variant="lime">
            Sign in
          </ComicButton>
        )}
      </div>
    </header>
  );
}

import Link from "next/link";
import type { EventRow } from "@/lib/events/queries";
import { formatDateParts, tzLabel } from "@/lib/events/format";

const ACCENT: Record<EventRow["accent"], string> = {
  blue: "bg-brand-blue text-white",
  lime: "bg-brand-lime text-brand-ink",
  purple: "bg-brand-purple text-white",
};

/** A linked event row with the comic date plate. */
export function EventCard({
  event,
  goingCount,
}: {
  event: EventRow;
  goingCount?: number;
}) {
  const d = formatDateParts(event.starts_at);

  return (
    <Link
      href={`/events/${event.slug}`}
      className="focus-comic group flex items-stretch gap-4 rounded-[var(--radius-comic)] border-ink bg-surface p-4 shadow-comic transition-transform duration-100 hover:-translate-y-0.5 hover:shadow-comic-lg"
    >
      <div
        className={`flex w-20 shrink-0 flex-col items-center justify-center rounded-md border-ink ${ACCENT[event.accent]} py-2 font-display leading-none`}
      >
        <span className="text-sm uppercase tracking-widest">{d.month}</span>
        <span className="text-4xl">{d.day}</span>
        <span className="text-xs uppercase opacity-90">{d.weekday}</span>
      </div>

      <div className="flex min-w-0 flex-col justify-center">
        <span className="font-mono text-xs uppercase tracking-widest text-muted">
          {d.time} {tzLabel(event.timezone)}
          {event.host ? ` · ${event.host}` : ""}
        </span>
        <h3 className="mt-1 font-display text-xl uppercase leading-tight tracking-wide text-brand-ink">
          {event.title}
        </h3>
        {event.summary && (
          <p className="mt-1 line-clamp-2 text-sm text-brand-ink/70">
            {event.summary}
          </p>
        )}
        {typeof goingCount === "number" && goingCount > 0 && (
          <span className="mt-1 font-mono text-xs uppercase tracking-widest text-muted">
            {goingCount} going
          </span>
        )}
      </div>

      {event.is_live && (
        <span className="ml-auto self-start rounded-md border-ink bg-brand-purple px-2 py-0.5 font-display text-xs uppercase text-white">
          ● Live
        </span>
      )}
      {event.status === "cancelled" && (
        <span className="ml-auto self-start rounded-md border-ink bg-brand-ink px-2 py-0.5 font-display text-xs uppercase text-white">
          Cancelled
        </span>
      )}
    </Link>
  );
}

"use client";

import { useFormStatus } from "react-dom";
import { setRsvp, cancelRsvp } from "@/lib/events/actions";
import { ComicButton } from "@/components/brand/comic-button";
import type { RsvpStatus } from "@/lib/events/queries";

type Variant = "blue" | "lime" | "purple" | "ink";

function SubmitButton({
  children,
  variant,
  size,
}: {
  children: React.ReactNode;
  variant: Variant;
  size?: "md" | "lg";
}) {
  const { pending } = useFormStatus();
  return (
    <ComicButton type="submit" variant={variant} size={size} disabled={pending}>
      {pending ? "…" : children}
    </ComicButton>
  );
}

/**
 * RSVP controls. Logged-out visitors get the funnel: a sign-in CTA that returns
 * them to this event. Logged-in members get going/interested toggles + cancel.
 */
export function RsvpControls({
  eventId,
  slug,
  currentStatus,
  isAuthed,
  loginHref,
  disabled,
}: {
  eventId: string;
  slug: string;
  currentStatus: RsvpStatus | null;
  isAuthed: boolean;
  loginHref: string;
  disabled?: boolean;
}) {
  if (disabled) {
    return (
      <p className="font-display text-lg uppercase tracking-wide text-brand-ink/60">
        RSVPs are closed for this event.
      </p>
    );
  }

  if (!isAuthed) {
    return (
      <div className="flex flex-col gap-2">
        <ComicButton href={loginHref} variant="blue" size="lg">
          RSVP — sign in to join
        </ComicButton>
        <p className="font-mono text-xs uppercase tracking-widest text-muted">
          Free · Sign in with GitHub to RSVP
        </p>
      </div>
    );
  }

  const hidden = (
    <>
      <input type="hidden" name="event_id" value={eventId} />
      <input type="hidden" name="slug" value={slug} />
    </>
  );

  return (
    <div className="flex flex-wrap items-center gap-3">
      <form action={setRsvp}>
        {hidden}
        <input type="hidden" name="status" value="going" />
        <SubmitButton variant={currentStatus === "going" ? "lime" : "ink"} size="lg">
          {currentStatus === "going" ? "✓ You're going" : "I'm going"}
        </SubmitButton>
      </form>

      <form action={setRsvp}>
        {hidden}
        <input type="hidden" name="status" value="interested" />
        <SubmitButton
          variant={currentStatus === "interested" ? "purple" : "ink"}
        >
          {currentStatus === "interested" ? "✓ Interested" : "Interested"}
        </SubmitButton>
      </form>

      {currentStatus && (
        <form action={cancelRsvp}>
          {hidden}
          <button
            type="submit"
            className="focus-comic font-display text-sm uppercase tracking-wide text-brand-ink/60 underline underline-offset-4 hover:text-brand-purple"
          >
            Cancel RSVP
          </button>
        </form>
      )}
    </div>
  );
}

import Image from "next/image";
import Link from "next/link";
import type { Attendee } from "@/lib/events/queries";

function initial(name: string | null, username: string | null) {
  return (name ?? username ?? "?").charAt(0).toUpperCase();
}

/** "Who's going" — avatar + handle grid, linking to public profiles. */
export function Attendees({
  attendees,
  total,
}: {
  attendees: Attendee[];
  total: number;
}) {
  if (total === 0) {
    return (
      <p className="text-brand-ink/60">
        No one&apos;s RSVP&apos;d yet — be the first to assemble.
      </p>
    );
  }

  const extra = total - attendees.length;

  return (
    <div>
      <ul className="flex flex-wrap gap-3">
        {attendees.map((a) => {
          const name = a.display_name ?? a.username ?? "member";
          const body = (
            <>
              {a.avatar_url ? (
                <Image
                  src={a.avatar_url}
                  alt={name}
                  width={36}
                  height={36}
                  className="h-9 w-9 rounded-full border-[2px] border-brand-ink object-cover"
                />
              ) : (
                <span className="flex h-9 w-9 items-center justify-center rounded-full border-[2px] border-brand-ink bg-brand-lime font-display text-brand-ink">
                  {initial(a.display_name, a.username)}
                </span>
              )}
              <span className="font-mono text-sm text-brand-ink">
                {a.username ? `@${a.username}` : name}
              </span>
            </>
          );

          return (
            <li key={a.user_id}>
              {a.username ? (
                <Link
                  href={`/u/${a.username}`}
                  className="focus-comic flex items-center gap-2 rounded-full border-ink bg-surface py-1 pl-1 pr-3 shadow-comic-sm transition-transform hover:-translate-y-0.5"
                >
                  {body}
                </Link>
              ) : (
                <span className="flex items-center gap-2 rounded-full border-ink bg-surface py-1 pl-1 pr-3 shadow-comic-sm">
                  {body}
                </span>
              )}
            </li>
          );
        })}
      </ul>
      {extra > 0 && (
        <p className="mt-3 font-mono text-xs uppercase tracking-widest text-muted">
          + {extra} more going
        </p>
      )}
    </div>
  );
}

"use client";

import { useActionState } from "react";
import {
  createEvent,
  updateEvent,
  type EventFormState,
} from "@/lib/events/actions";
import { toDatetimeLocalValue } from "@/lib/events/format";
import { ComicButton } from "@/components/brand/comic-button";
import type { EventRow } from "@/lib/events/queries";

const inputClass =
  "rounded-[var(--radius-comic)] border-ink bg-white px-4 py-3 text-brand-ink outline-none focus:shadow-comic-sm";
const labelClass =
  "font-display text-lg uppercase tracking-wide text-brand-ink";

function Field({
  label,
  children,
  hint,
}: {
  label: string;
  children: React.ReactNode;
  hint?: string;
}) {
  return (
    <div className="flex flex-col gap-1">
      <span className={labelClass}>{label}</span>
      {children}
      {hint && <span className="text-xs text-brand-ink/55">{hint}</span>}
    </div>
  );
}

export function EventForm({
  mode,
  event,
}: {
  mode: "create" | "edit";
  event?: EventRow;
}) {
  const action = mode === "create" ? createEvent : updateEvent;
  const [state, formAction, pending] = useActionState<EventFormState, FormData>(
    action,
    {},
  );

  return (
    <form action={formAction} className="flex flex-col gap-5">
      {mode === "edit" && event && (
        <input type="hidden" name="id" value={event.id} />
      )}

      <Field label="Title">
        <input
          name="title"
          required
          defaultValue={event?.title ?? ""}
          placeholder="Ship-it Thursday: agents in production"
          className={inputClass}
        />
      </Field>

      <Field label="Slug" hint="Permanent URL: /events/your-slug — lowercase, hyphens.">
        <input
          name="slug"
          required
          defaultValue={event?.slug ?? ""}
          placeholder="ship-it-thursday-agents"
          className={inputClass}
        />
      </Field>

      <Field label="Summary" hint="Short blurb shown on cards (max 200 chars).">
        <input
          name="summary"
          defaultValue={event?.summary ?? ""}
          maxLength={200}
          placeholder="What this session is about, in a sentence."
          className={inputClass}
        />
      </Field>

      <Field label="Description">
        <textarea
          name="description"
          rows={5}
          defaultValue={event?.description ?? ""}
          placeholder="The full details."
          className={inputClass}
        />
      </Field>

      <div className="grid gap-5 sm:grid-cols-2">
        <Field label="Starts" hint="Interpreted as the timezone below.">
          <input
            type="datetime-local"
            name="starts_at"
            required
            defaultValue={
              event ? toDatetimeLocalValue(event.starts_at) : ""
            }
            className={inputClass}
          />
        </Field>
        <Field label="Ends (optional)">
          <input
            type="datetime-local"
            name="ends_at"
            defaultValue={
              event?.ends_at ? toDatetimeLocalValue(event.ends_at) : ""
            }
            className={inputClass}
          />
        </Field>
      </div>

      <div className="grid gap-5 sm:grid-cols-2">
        <Field label="Timezone">
          <input
            name="timezone"
            defaultValue={event?.timezone ?? "America/New_York"}
            placeholder="America/New_York"
            className={inputClass}
          />
        </Field>
        <Field label="Host label">
          <input
            name="host"
            defaultValue={event?.host ?? ""}
            placeholder="Live build stream"
            className={inputClass}
          />
        </Field>
      </div>

      <Field label="Location" hint="Leave blank for virtual-only.">
        <input
          name="location"
          defaultValue={event?.location ?? ""}
          placeholder="Virtual / Zoom / a city"
          className={inputClass}
        />
      </Field>

      <label className="flex items-center gap-3">
        <input
          type="checkbox"
          name="is_virtual"
          defaultChecked={event?.is_virtual ?? true}
          className="h-5 w-5 rounded border-ink"
        />
        <span className={labelClass}>Virtual event</span>
      </label>

      <div className="grid gap-5 sm:grid-cols-2">
        <Field label="Accent">
          <select
            name="accent"
            defaultValue={event?.accent ?? "blue"}
            className={inputClass}
          >
            <option value="blue">Blue</option>
            <option value="lime">Lime</option>
            <option value="purple">Purple</option>
          </select>
        </Field>
        <Field label="Status" hint="Only published events are public.">
          <select
            name="status"
            defaultValue={event?.status ?? "draft"}
            className={inputClass}
          >
            <option value="draft">Draft</option>
            <option value="published">Published</option>
            <option value="cancelled">Cancelled</option>
          </select>
        </Field>
      </div>

      <div className="flex items-center gap-4">
        <ComicButton variant="blue" type="submit" disabled={pending}>
          {pending
            ? "Saving…"
            : mode === "create"
              ? "Create event"
              : "Save changes"}
        </ComicButton>
        {state.error && (
          <span className="text-sm text-brand-purple">{state.error}</span>
        )}
      </div>
    </form>
  );
}

