import * as z from "zod";

export const topicSchema = z.object({
  title: z
    .string()
    .trim()
    .min(5, { error: "Give your topic a clear title." })
    .max(140, { error: "Keep the title under 140 characters." }),
  body: z
    .string()
    .trim()
    .min(10, { error: "Add some detail to start the discussion." })
    .max(10000, { error: "Posts are limited to 10,000 characters." }),
  category_id: z.uuid({ error: "Pick a category." }),
});

export const replySchema = z.object({
  body: z
    .string()
    .trim()
    .min(1, { error: "Write a reply." })
    .max(10000, { error: "Replies are limited to 10,000 characters." }),
});

export const reportSchema = z.object({
  target_type: z.enum(["topic", "post"]),
  target_id: z.uuid(),
  reason: z.string().trim().max(500).optional().or(z.literal("")),
});

/** Turn a title into a URL-safe base slug. A random suffix is added at insert. */
export function slugify(input: string): string {
  const base = input
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 60);
  return base || "topic";
}

import "server-only";

import { createClient } from "@/lib/supabase/server";

export type Category = {
  id: string;
  slug: string;
  name: string;
  description: string | null;
  position: number;
};

export type ForumAuthor = {
  username: string | null;
  display_name: string | null;
  avatar_url: string | null;
} | null;

export type TopicListItem = {
  id: string;
  slug: string;
  title: string;
  reply_count: number;
  is_pinned: boolean;
  is_locked: boolean;
  last_activity_at: string;
  created_at: string;
  category: { slug: string; name: string } | null;
  author: ForumAuthor;
};

export type TopicDetail = TopicListItem & {
  body: string;
  author_id: string | null;
  category_id: string | null;
};

export type PostItem = {
  id: string;
  body: string;
  created_at: string;
  author_id: string | null;
  author: ForumAuthor;
};

export type ReportItem = {
  id: string;
  target_type: "topic" | "post";
  target_id: string;
  reason: string | null;
  status: "open" | "resolved" | "dismissed";
  created_at: string;
  reporter: ForumAuthor;
};

const TOPIC_LIST_SELECT =
  "id, slug, title, reply_count, is_pinned, is_locked, last_activity_at, created_at, category:categories ( slug, name ), author:profiles ( username, display_name, avatar_url )";

const TOPIC_DETAIL_SELECT = `${TOPIC_LIST_SELECT}, body, author_id, category_id`;

const POST_SELECT =
  "id, body, created_at, author_id, author:profiles ( username, display_name, avatar_url )";

export async function listCategories(): Promise<Category[]> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("categories")
    .select("id, slug, name, description, position")
    .order("position", { ascending: true });
  if (error) throw error;
  return (data ?? []) as Category[];
}

export async function listTopics(opts?: {
  categorySlug?: string;
  limit?: number;
}): Promise<TopicListItem[]> {
  const supabase = await createClient();

  let categoryId: string | undefined;
  if (opts?.categorySlug) {
    const { data: cat } = await supabase
      .from("categories")
      .select("id")
      .eq("slug", opts.categorySlug)
      .maybeSingle();
    if (!cat) return [];
    categoryId = (cat as { id: string }).id;
  }

  let query = supabase.from("topics").select(TOPIC_LIST_SELECT);
  if (categoryId) query = query.eq("category_id", categoryId);
  query = query
    .order("is_pinned", { ascending: false })
    .order("last_activity_at", { ascending: false });
  if (opts?.limit) query = query.limit(opts.limit);

  const { data, error } = await query;
  if (error) throw error;
  return (data ?? []) as unknown as TopicListItem[];
}

export async function getTopicBySlug(slug: string): Promise<TopicDetail | null> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("topics")
    .select(TOPIC_DETAIL_SELECT)
    .eq("slug", slug)
    .maybeSingle();
  if (error) throw error;
  return (data as unknown as TopicDetail) ?? null;
}

export async function listPosts(topicId: string): Promise<PostItem[]> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("posts")
    .select(POST_SELECT)
    .eq("topic_id", topicId)
    .order("created_at", { ascending: true });
  if (error) throw error;
  return (data ?? []) as unknown as PostItem[];
}

/** Open moderation reports (admin-only; RLS enforces). */
export async function listOpenReports(): Promise<ReportItem[]> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("reports")
    .select(
      "id, target_type, target_id, reason, status, created_at, reporter:profiles!reports_reporter_id_fkey ( username, display_name, avatar_url )",
    )
    .eq("status", "open")
    .order("created_at", { ascending: false });
  if (error) throw error;
  return (data ?? []) as unknown as ReportItem[];
}

"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { requireAdmin, requireUser } from "@/lib/auth/dal";
import { topicSchema, replySchema, reportSchema } from "@/lib/validation/forum";
import { slugify } from "@/lib/forum/slug";

export type ForumFormState = { error?: string; ok?: boolean };

/** Create a topic, generating a unique permanent slug (retry on collision). */
export async function createTopic(
  _prev: ForumFormState,
  formData: FormData,
): Promise<ForumFormState> {
  const user = await requireUser();

  const parsed = topicSchema.safeParse({
    title: formData.get("title"),
    body: formData.get("body"),
    category_id: formData.get("category_id"),
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Check the form." };
  }

  const supabase = await createClient();
  const base = slugify(parsed.data.title);

  let createdSlug: string | null = null;
  for (let attempt = 0; attempt < 4; attempt += 1) {
    const slug = `${base}-${Math.random().toString(36).slice(2, 8)}`;
    const { data, error } = await supabase
      .from("topics")
      .insert({
        slug,
        title: parsed.data.title,
        body: parsed.data.body,
        category_id: parsed.data.category_id,
        author_id: user.id,
      })
      .select("slug")
      .single();

    if (!error) {
      createdSlug = (data as { slug: string }).slug;
      break;
    }
    if (error.code !== "23505") return { error: error.message };
  }

  if (!createdSlug) {
    return { error: "Could not generate a unique URL. Please try again." };
  }

  revalidatePath("/discussions");
  redirect(`/discussions/${createdSlug}`);
}

/** Post a reply to a topic (blocked if the topic is locked). */
export async function createReply(
  _prev: ForumFormState,
  formData: FormData,
): Promise<ForumFormState> {
  const user = await requireUser();

  const topicId = String(formData.get("topic_id") ?? "");
  const slug = String(formData.get("slug") ?? "");
  if (!topicId) return { error: "Missing topic." };

  const parsed = replySchema.safeParse({ body: formData.get("body") });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Write a reply." };
  }

  const supabase = await createClient();

  const { data: topic } = await supabase
    .from("topics")
    .select("is_locked")
    .eq("id", topicId)
    .maybeSingle();
  if ((topic as { is_locked: boolean } | null)?.is_locked) {
    return { error: "This topic is locked." };
  }

  const { error } = await supabase
    .from("posts")
    .insert({ topic_id: topicId, body: parsed.data.body, author_id: user.id });
  if (error) return { error: error.message };

  if (slug) revalidatePath(`/discussions/${slug}`);
  return { ok: true };
}

/** Delete a topic. RLS restricts to the author or an admin. */
export async function deleteTopic(formData: FormData): Promise<void> {
  await requireUser();
  const id = String(formData.get("id") ?? "");
  if (!id) return;

  const supabase = await createClient();
  const { error } = await supabase.from("topics").delete().eq("id", id);
  if (error) throw error;

  revalidatePath("/discussions");
  redirect("/discussions");
}

/** Delete a reply. RLS restricts to the author or an admin. */
export async function deletePost(formData: FormData): Promise<void> {
  await requireUser();
  const id = String(formData.get("id") ?? "");
  const slug = String(formData.get("slug") ?? "");
  if (!id) return;

  const supabase = await createClient();
  const { error } = await supabase.from("posts").delete().eq("id", id);
  if (error) throw error;

  if (slug) revalidatePath(`/discussions/${slug}`);
}

/** Lock/unlock a topic (admin/moderator only). */
export async function setTopicLock(formData: FormData): Promise<void> {
  await requireAdmin();
  const id = String(formData.get("id") ?? "");
  const slug = String(formData.get("slug") ?? "");
  const locked = formData.get("locked") === "true";
  if (!id) return;

  const supabase = await createClient();
  const { error } = await supabase
    .from("topics")
    .update({ is_locked: locked })
    .eq("id", id);
  if (error) throw error;

  if (slug) revalidatePath(`/discussions/${slug}`);
}

/** Pin/unpin a topic (admin/moderator only). */
export async function setTopicPin(formData: FormData): Promise<void> {
  await requireAdmin();
  const id = String(formData.get("id") ?? "");
  const slug = String(formData.get("slug") ?? "");
  const pinned = formData.get("pinned") === "true";
  if (!id) return;

  const supabase = await createClient();
  const { error } = await supabase
    .from("topics")
    .update({ is_pinned: pinned })
    .eq("id", id);
  if (error) throw error;

  if (slug) revalidatePath(`/discussions/${slug}`);
}

/** File a moderation report against a topic or post. */
export async function reportContent(
  _prev: ForumFormState,
  formData: FormData,
): Promise<ForumFormState> {
  const user = await requireUser();

  const parsed = reportSchema.safeParse({
    target_type: formData.get("target_type"),
    target_id: formData.get("target_id"),
    reason: formData.get("reason"),
  });
  if (!parsed.success) return { error: "Could not file that report." };

  const supabase = await createClient();
  const { error } = await supabase.from("reports").insert({
    reporter_id: user.id,
    target_type: parsed.data.target_type,
    target_id: parsed.data.target_id,
    reason: parsed.data.reason && parsed.data.reason !== "" ? parsed.data.reason : null,
  });
  if (error) return { error: error.message };

  return { ok: true };
}

/** Resolve or dismiss a report (admin/moderator only). */
export async function resolveReport(formData: FormData): Promise<void> {
  const admin = await requireAdmin();
  const id = String(formData.get("id") ?? "");
  const status = formData.get("status") === "dismissed" ? "dismissed" : "resolved";
  if (!id) return;

  const supabase = await createClient();
  const { error } = await supabase
    .from("reports")
    .update({
      status,
      resolved_by: admin.id,
      resolved_at: new Date().toISOString(),
    })
    .eq("id", id);
  if (error) throw error;

  revalidatePath("/admin/reports");
}

import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import rehypeSanitize from "rehype-sanitize";

/**
 * Renders user-authored markdown. XSS-safe by construction:
 * - react-markdown renders to React elements (no dangerouslySetInnerHTML)
 * - rehype-sanitize applies a safe default schema
 * - rehype-raw is intentionally NOT used, so embedded HTML is escaped, not run
 */
export function Markdown({ children }: { children: string }) {
  return (
    <div className="markdown">
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        rehypePlugins={[rehypeSanitize]}
      >
        {children}
      </ReactMarkdown>
    </div>
  );
}

