"use client";

import { useActionState, type ReactNode } from "react";
import { createTopic, type ForumFormState } from "@/lib/forum/actions";
import { ComicButton } from "@/components/brand/comic-button";
import type { Category } from "@/lib/forum/queries";

const inputClass =
  "rounded-[var(--radius-comic)] border-ink bg-white px-4 py-3 text-brand-ink outline-none focus:shadow-comic-sm";
const labelClass =
  "font-display text-lg uppercase tracking-wide text-brand-ink";

function Field({
  label,
  children,
  hint,
}: {
  label: string;
  children: ReactNode;
  hint?: string;
}) {
  return (
    <div className="flex flex-col gap-1">
      <span className={labelClass}>{label}</span>
      {children}
      {hint && <span className="text-xs text-brand-ink/55">{hint}</span>}
    </div>
  );
}

export function NewTopicForm({ categories }: { categories: Category[] }) {
  const [state, action, pending] = useActionState<ForumFormState, FormData>(
    createTopic,
    {},
  );

  return (
    <form action={action} className="flex flex-col gap-5">
      <Field label="Category">
        <select name="category_id" required defaultValue="" className={inputClass}>
          <option value="" disabled>
            Choose a category
          </option>
          {categories.map((c) => (
            <option key={c.id} value={c.id}>
              {c.name}
            </option>
          ))}
        </select>
      </Field>

      <Field label="Title">
        <input
          name="title"
          required
          maxLength={140}
          placeholder="What do you want to talk about?"
          className={inputClass}
        />
      </Field>

      <Field label="Body" hint="Markdown supported — **bold**, lists, `code`, links.">
        <textarea
          name="body"
          rows={10}
          required
          placeholder="Share your thoughts…"
          className={inputClass}
        />
      </Field>

      <div className="flex items-center gap-4">
        <ComicButton variant="blue" type="submit" disabled={pending}>
          {pending ? "Posting…" : "Post topic"}
        </ComicButton>
        {state.error && (
          <span className="text-sm text-brand-purple">{state.error}</span>
        )}
      </div>
    </form>
  );
}

"use client";

import { useActionState, useEffect, useRef } from "react";
import { createReply, type ForumFormState } from "@/lib/forum/actions";
import { ComicButton } from "@/components/brand/comic-button";

export function ReplyForm({
  topicId,
  slug,
}: {
  topicId: string;
  slug: string;
}) {
  const [state, action, pending] = useActionState<ForumFormState, FormData>(
    createReply,
    {},
  );
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    if (state.ok) formRef.current?.reset();
  }, [state.ok]);

  return (
    <form ref={formRef} action={action} className="flex flex-col gap-3">
      <input type="hidden" name="topic_id" value={topicId} />
      <input type="hidden" name="slug" value={slug} />
      <textarea
        name="body"
        rows={4}
        required
        placeholder="Write a reply… markdown supported."
        className="rounded-[var(--radius-comic)] border-ink bg-white px-4 py-3 text-brand-ink outline-none focus:shadow-comic-sm"
      />
      <div className="flex items-center gap-4">
        <ComicButton variant="blue" type="submit" disabled={pending}>
          {pending ? "Posting…" : "Reply"}
        </ComicButton>
        {state.error && (
          <span className="text-sm text-brand-purple">{state.error}</span>
        )}
      </div>
    </form>
  );
}

"use client";

import { useActionState } from "react";
import { reportContent, type ForumFormState } from "@/lib/forum/actions";

export function ReportButton({
  targetType,
  targetId,
}: {
  targetType: "topic" | "post";
  targetId: string;
}) {
  const [state, action, pending] = useActionState<ForumFormState, FormData>(
    reportContent,
    {},
  );

  if (state.ok) {
    return (
      <span className="font-mono text-xs uppercase tracking-widest text-muted">
