function initial(name: string | null, username: string) {
  return (name ?? username).charAt(0).toUpperCase();
}

/**
 * Home-page community pulse: latest discussions + newest members, from live
 * data. Degrades gracefully pre-launch — empty states invite the first post
 * rather than looking abandoned.
 */
export async function CommunityActivity() {
  const [topics, members] = await Promise.all([
    listTopics({ limit: 4 }),
    listRecentMembers(10),
  ]);

  return (
    <section
      id="activity"
      className="halftone scroll-mt-24 border-y-[3px] border-brand-ink px-6 py-16 sm:py-20"
    >
      <div className="mx-auto max-w-6xl">
        <div className="flex flex-col items-center text-center">
          <span className="inline-block rotate-[-2deg] rounded-md border-ink bg-brand-lime px-3 py-1 font-display text-lg uppercase tracking-wide text-brand-ink shadow-comic-sm">
