/** Fixed emoji reaction set for repos (useful / cool / mind-blown / star). */
export const REACTION_EMOJIS = ["👍", "🔥", "🤯", "⭐"] as const;
export type ReactionEmoji = (typeof REACTION_EMOJIS)[number];

export function isReactionEmoji(value: string): value is ReactionEmoji {
  return (REACTION_EMOJIS as readonly string[]).includes(value);
}

import "server-only";

/** Extract owner/name from a GitHub URL (or owner/name shorthand). */
export function parseGithubUrl(
  url: string,
): { owner: string; name: string } | null {
  const m = url.trim().match(/github\.com[/:]([^/\s]+)\/([^/\s#?]+)/i);
  if (!m) return null;
  return { owner: m[1], name: m[2].replace(/\.git$/i, "") };
}

export type RepoMeta = {
  description: string | null;
  homepage_url: string | null;
  stars: number | null;
  language: string | null;
  owner_avatar_url: string | null;
};

/** Fetch public repo metadata from the GitHub API. Returns null on any failure
 * (rate limit, private, not found) so submission still works with the URL. */
export async function fetchRepoMeta(
  owner: string,
  name: string,
): Promise<RepoMeta | null> {
  try {
    const headers: Record<string, string> = {
      Accept: "application/vnd.github+json",
      "User-Agent": "DevsAssemble",
    };
    if (process.env.GITHUB_API_TOKEN) {
      headers.Authorization = `Bearer ${process.env.GITHUB_API_TOKEN}`;
    }
    const res = await fetch(`https://api.github.com/repos/${owner}/${name}`, {
      headers,
    });
    if (!res.ok) return null;
    const d = (await res.json()) as {
      description?: string | null;
      homepage?: string | null;
      stargazers_count?: number;
      language?: string | null;
      owner?: { avatar_url?: string | null };
    };
    return {
      description: d.description ?? null,
      homepage_url: d.homepage || null,
      stars: typeof d.stargazers_count === "number" ? d.stargazers_count : null,
      language: d.language ?? null,
      owner_avatar_url: d.owner?.avatar_url ?? null,
    };
  } catch {
    return null;
  }
}

import * as z from "zod";

export const repoSubmitSchema = z.object({
  github_url: z
    .url({ error: "Paste a GitHub repository URL." })
    .max(300),
  kind: z.enum(["build", "recommendation"]),
  note: z
    .string()
    .trim()
    .max(500, { error: "Keep your note under 500 characters." })
    .optional()
    .or(z.literal("")),
});

import "server-only";

import { createClient } from "@/lib/supabase/server";

export type RepoKind = "build" | "recommendation";

export type RepoSubmitter = {
  username: string | null;
  display_name: string | null;
  avatar_url: string | null;
} | null;

type RepoBase = {
  id: string;
  owner: string;
  name: string;
  github_url: string;
  description: string | null;
  homepage_url: string | null;
  stars: number | null;
  language: string | null;
  owner_avatar_url: string | null;
  kind: RepoKind;
  note: string | null;
  submitted_by: string | null;
  created_at: string;
  submitter: RepoSubmitter;
};

export type RepoItem = RepoBase & {
  reactions: Record<string, number>;
  reactionCount: number;
  myReactions: string[];
};

const REPO_SELECT =
  "id, owner, name, github_url, description, homepage_url, stars, language, owner_avatar_url, kind, note, submitted_by, created_at, submitter:profiles!repos_submitted_by_fkey ( username, display_name, avatar_url )";

export async function listRepos(opts?: {
  sort?: "new" | "top";
  kind?: RepoKind;
}): Promise<RepoItem[]> {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  let query = supabase.from("repos").select(REPO_SELECT);
  if (opts?.kind) query = query.eq("kind", opts.kind);
  query = query.order("created_at", { ascending: false }).limit(100);

  const { data, error } = await query;
  if (error) throw error;

  const repos = (data ?? []) as unknown as RepoBase[];
  const ids = repos.map((r) => r.id);
  if (ids.length === 0) return [];

  const { data: reactionRows, error: rErr } = await supabase
    .from("repo_reactions")
    .select("repo_id, emoji, user_id")
    .in("repo_id", ids);
  if (rErr) throw rErr;

  const agg = new Map<string, { counts: Record<string, number>; mine: string[] }>();
  for (const id of ids) agg.set(id, { counts: {}, mine: [] });
  for (const row of (reactionRows ?? []) as {
    repo_id: string;
    emoji: string;
    user_id: string;
  }[]) {
    const entry = agg.get(row.repo_id);
    if (!entry) continue;
    entry.counts[row.emoji] = (entry.counts[row.emoji] ?? 0) + 1;
    if (user && row.user_id === user.id) entry.mine.push(row.emoji);
  }

  const result: RepoItem[] = repos.map((r) => {
    const entry = agg.get(r.id)!;
    const reactionCount = Object.values(entry.counts).reduce((a, b) => a + b, 0);
    return { ...r, reactions: entry.counts, reactionCount, myReactions: entry.mine };
  });

  if (opts?.sort === "top") {
    result.sort(
      (a, b) =>
        b.reactionCount - a.reactionCount ||
        (a.created_at < b.created_at ? 1 : -1),
    );
  }
  return result;
}

"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { requireUser } from "@/lib/auth/dal";
import { repoSubmitSchema } from "@/lib/validation/repos";
import { parseGithubUrl, fetchRepoMeta } from "@/lib/repos/github";
import { isReactionEmoji } from "@/lib/repos/reactions";

export type RepoFormState = { error?: string };

export async function submitRepo(
  _prev: RepoFormState,
  formData: FormData,
): Promise<RepoFormState> {
  const user = await requireUser();

  const parsed = repoSubmitSchema.safeParse({
    github_url: formData.get("github_url"),
    kind: formData.get("kind"),
    note: formData.get("note"),
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Check the form." };
  }

  const gh = parseGithubUrl(parsed.data.github_url);
  if (!gh) return { error: "That doesn't look like a GitHub repository URL." };

  const meta = await fetchRepoMeta(gh.owner, gh.name);

  const supabase = await createClient();
  const { error } = await supabase.from("repos").insert({
    owner: gh.owner.toLowerCase(),
    name: gh.name.toLowerCase(),
    github_url: `https://github.com/${gh.owner}/${gh.name}`,
    description: meta?.description ?? null,
    homepage_url: meta?.homepage_url ?? null,
    stars: meta?.stars ?? null,
    language: meta?.language ?? null,
    owner_avatar_url: meta?.owner_avatar_url ?? null,
    kind: parsed.data.kind,
    note: parsed.data.note && parsed.data.note !== "" ? parsed.data.note : null,
    submitted_by: user.id,
    last_synced_at: meta ? new Date().toISOString() : null,
  });

  if (error) {
    if (error.code === "23505") return { error: "That repo's already on the board." };
    return { error: error.message };
  }

  revalidatePath("/projects");
  redirect("/projects");
}

/** Toggle one emoji reaction for the current user on a repo. */
export async function toggleReaction(formData: FormData): Promise<void> {
  const user = await requireUser();
  const repoId = String(formData.get("repo_id") ?? "");
  const emoji = String(formData.get("emoji") ?? "");
  if (!repoId || !isReactionEmoji(emoji)) return;

  const supabase = await createClient();
  const { data: existing } = await supabase
    .from("repo_reactions")
    .select("repo_id")
    .eq("repo_id", repoId)
    .eq("user_id", user.id)
    .eq("emoji", emoji)
    .maybeSingle();

  if (existing) {
    await supabase
      .from("repo_reactions")
      .delete()
      .eq("repo_id", repoId)
      .eq("user_id", user.id)
      .eq("emoji", emoji);
  } else {
    await supabase
      .from("repo_reactions")
      .insert({ repo_id: repoId, user_id: user.id, emoji });
  }

  revalidatePath("/projects");
}

"use client";

import { toggleReaction } from "@/lib/repos/actions";
import { REACTION_EMOJIS } from "@/lib/repos/reactions";

const chip =
  "focus-comic inline-flex items-center gap-1 rounded-full border-[2px] border-brand-ink px-3 py-1 text-sm shadow-comic-sm transition-transform hover:-translate-y-0.5";

export function ReactionBar({
  repoId,
  reactions,
  myReactions,
  isAuthed,
  loginHref,
}: {
  repoId: string;
  reactions: Record<string, number>;
  myReactions: string[];
  isAuthed: boolean;
  loginHref: string;
}) {
  if (!isAuthed) {
    return (
      <div className="flex flex-wrap gap-2">
        {REACTION_EMOJIS.map((e) => (
          <a
            key={e}
            href={loginHref}
            title="Sign in to react"
            className={`${chip} bg-surface text-brand-ink`}
          >
            <span aria-hidden>{e}</span>
            {reactions[e] ? (
              <span className="font-mono text-xs">{reactions[e]}</span>
            ) : null}
          </a>
        ))}
      </div>
    );
  }

  return (
    <div className="flex flex-wrap gap-2">
      {REACTION_EMOJIS.map((e) => {
        const active = myReactions.includes(e);
        const count = reactions[e] ?? 0;
        return (
          <form key={e} action={toggleReaction}>
            <input type="hidden" name="repo_id" value={repoId} />
            <input type="hidden" name="emoji" value={e} />
            <button
              type="submit"
              aria-pressed={active}
              className={`${chip} ${active ? "bg-brand-lime text-brand-ink" : "bg-surface text-brand-ink"}`}
            >
              <span aria-hidden>{e}</span>
              {count > 0 && <span className="font-mono text-xs">{count}</span>}
            </button>
          </form>
        );
      })}
    </div>
  );
}

import Image from "next/image";
import Link from "next/link";
import { ReactionBar } from "./reaction-bar";
import type { RepoItem } from "@/lib/repos/queries";

export function RepoCard({
  repo,
  isAuthed,
  loginHref,
}: {
  repo: RepoItem;
  isAuthed: boolean;
  loginHref: string;
}) {
  return (
    <article className="flex flex-col rounded-[var(--radius-comic)] border-ink bg-surface p-5 shadow-comic">
      <div className="flex items-start gap-3">
        {repo.owner_avatar_url ? (
          <Image
            src={repo.owner_avatar_url}
            alt={repo.owner}
            width={40}
            height={40}
            className="h-10 w-10 rounded-md border-[2px] border-brand-ink object-cover"
          />
        ) : (
          <span className="flex h-10 w-10 items-center justify-center rounded-md border-[2px] border-brand-ink bg-brand-cream font-display text-brand-ink">
            {repo.owner.charAt(0).toUpperCase()}
          </span>
        )}
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-2">
            <span
              className={`rounded-md border-[2px] border-brand-ink px-2 py-0.5 font-display text-xs uppercase ${
                repo.kind === "build"
                  ? "bg-brand-blue text-white"
                  : "bg-brand-lime text-brand-ink"
              }`}
            >
              {repo.kind === "build" ? "Build" : "Pick"}
            </span>
            {repo.language && (
              <span className="font-mono text-xs text-muted">
                {repo.language}
              </span>
            )}
            {typeof repo.stars === "number" && (
              <span className="font-mono text-xs text-muted">★ {repo.stars}</span>
            )}
          </div>
          <a
            href={repo.github_url}
            target="_blank"
            rel="noopener noreferrer"
            className="focus-comic mt-1 block truncate font-display text-xl uppercase tracking-wide text-brand-ink hover:text-brand-blue"
          >
            {repo.owner}/{repo.name}
          </a>
          {repo.description && (
            <p className="mt-1 line-clamp-2 text-sm text-brand-ink/75">
              {repo.description}
            </p>
          )}
        </div>
      </div>

      {repo.note && (
        <p className="mt-3 rounded-md border-[2px] border-brand-ink bg-brand-cream px-3 py-2 text-sm text-brand-ink/85">
          “{repo.note}”
        </p>
      )}

      <div className="mt-3 font-mono text-xs text-muted">
        shared by{" "}
        {repo.submitter?.username ? (
          <Link
            href={`/u/${repo.submitter.username}`}
            className="focus-comic hover:underline"
          >
            @{repo.submitter.username}
          </Link>
        ) : (
          "a member"
        )}
      </div>

      <div className="mt-3">
        <ReactionBar
          repoId={repo.id}
          reactions={repo.reactions}
          myReactions={repo.myReactions}
          isAuthed={isAuthed}
          loginHref={loginHref}
        />
      </div>
    </article>
  );
}

"use client";

import { useActionState } from "react";
import { submitRepo, type RepoFormState } from "@/lib/repos/actions";
import { ComicButton } from "@/components/brand/comic-button";
import { ChoiceChips } from "@/components/ui/choice-chips";

const inputClass =
  "rounded-[var(--radius-comic)] border-ink bg-white px-4 py-3 text-brand-ink outline-none focus:shadow-comic-sm";
const labelClass =
  "font-display text-lg uppercase tracking-wide text-brand-ink";

export function SubmitRepoForm() {
  const [state, action, pending] = useActionState<RepoFormState, FormData>(
    submitRepo,
    {},
  );

  return (
    <form action={action} className="flex flex-col gap-5">
      <div className="flex flex-col gap-1">
        <span className={labelClass}>GitHub URL</span>
        <input
          name="github_url"
          required
          placeholder="https://github.com/owner/repo"
          className={inputClass}
        />
        <span className="text-xs text-brand-ink/55">
          We&apos;ll pull the name, description, stars, and language automatically.
        </span>
      </div>

      <div className="flex flex-col gap-1">
        <span className={labelClass}>Type</span>
        <ChoiceChips
          name="kind"
          defaultValue="recommendation"
          options={[
            { value: "build", label: "I built this" },
            { value: "recommendation", label: "A cool find" },
          ]}
        />
      </div>

      <div className="flex flex-col gap-1">
        <span className={labelClass}>Note</span>
        <textarea
          name="note"
          rows={3}
          maxLength={500}
          placeholder="What makes it useful or cool? (optional)"
          className={inputClass}
        />
      </div>

      <div className="flex items-center gap-4">
        <ComicButton variant="blue" type="submit" disabled={pending}>
          {pending ? "Adding…" : "Add to the board"}
        </ComicButton>
        {state.error && (
          <span className="text-sm text-brand-purple">{state.error}</span>
        )}
      </div>
    </form>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { PublicHeader } from "@/components/site/public-header";
import { SiteFooter } from "@/components/site/site-footer";
import { RepoCard } from "@/components/repos/repo-card";
import { ComicButton } from "@/components/brand/comic-button";
import { listRepos, type RepoKind } from "@/lib/repos/queries";
import { getSessionUser } from "@/lib/auth/dal";

export const metadata: Metadata = {
  title: "Projects",
  description:
    "GitHub repos the DevsAssemble community has built and recommends. Browse freely; sign in to add one or react.",
};

type ProjectsPageProps = {
  searchParams: Promise<{ sort?: string; kind?: string }>;
};

function buildHref(sort: string, kind?: string) {
  const p = new URLSearchParams();
  if (sort === "top") p.set("sort", "top");
  if (kind) p.set("kind", kind);
  const qs = p.toString();
  return qs ? `/projects?${qs}` : "/projects";
}

function chip(active: boolean) {
  return `focus-comic rounded-md border-ink px-3 py-1 font-display text-sm uppercase tracking-wide shadow-comic-sm ${
    active ? "bg-brand-ink text-white" : "bg-surface text-brand-ink"
  }`;
}

export default async function ProjectsPage({
  searchParams,
}: ProjectsPageProps) {
  const { sort, kind } = await searchParams;
  const sortMode = sort === "top" ? "top" : "new";
  const kindFilter: RepoKind | undefined =
    kind === "build" || kind === "recommendation" ? kind : undefined;

  const [repos, user] = await Promise.all([
    listRepos({ sort: sortMode, kind: kindFilter }),
    getSessionUser(),
  ]);

  const newHref = user ? "/projects/new" : "/login?next=/projects/new";
  const loginHref = "/login?next=/projects";

  return (
    <>
      <PublicHeader />
      <main id="main" className="mx-auto w-full max-w-5xl flex-1 px-6 py-12">
        <div className="flex items-center justify-between gap-4">
          <h1 className="font-display text-5xl uppercase tracking-wide text-brand-ink">
            Projects
          </h1>
          <ComicButton href={newHref} variant="blue">
            Add a project
          </ComicButton>
        </div>
        <p className="mt-2 max-w-2xl text-brand-ink/75">
          Repos the community has built and recommends. Browse freely — sign in
          to add one or react.
        </p>

        <nav className="mt-6 flex flex-wrap items-center gap-2" aria-label="Filter">
          <Link href={buildHref(sortMode)} className={chip(!kindFilter)}>
            All
          </Link>
          <Link
            href={buildHref(sortMode, "build")}
            className={chip(kindFilter === "build")}
          >
            Builds
          </Link>
          <Link
            href={buildHref(sortMode, "recommendation")}
            className={chip(kindFilter === "recommendation")}
          >
            Picks
          </Link>
          <span className="mx-1 h-5 w-[2px] bg-brand-ink/15" aria-hidden />
          <Link
            href={buildHref("new", kindFilter)}
            className={chip(sortMode === "new")}
          >
            Newest
          </Link>
          <Link
            href={buildHref("top", kindFilter)}
            className={chip(sortMode === "top")}
          >
            Most loved
          </Link>
        </nav>

        {repos.length > 0 ? (
          <div className="mt-8 grid gap-4 sm:grid-cols-2">
            {repos.map((repo) => (
              <RepoCard
                key={repo.id}
                repo={repo}
                isAuthed={Boolean(user)}
                loginHref={loginHref}
              />
            ))}
          </div>
        ) : (
          <div className="mt-8 rounded-[var(--radius-comic)] border-ink bg-surface p-10 text-center shadow-comic">
            <p className="font-display text-2xl uppercase tracking-wide text-brand-ink">
              No projects yet
            </p>
            <p className="mt-2 text-brand-ink/70">
              Be the first — share a repo you built or a tool you love.
            </p>
          </div>
        )}
      </main>
      <SiteFooter />
    </>
  );
}

