3	// RFC 5545 text escaping.
4	function escapeText(value: string): string {
5	  return value
6	    .replace(/\\/g, "\\\\")
7	    .replace(/;/g, "\\;")
8	    .replace(/,/g, "\\,")
9	    .replace(/\r?\n/g, "\\n");
10	}
11	
12	// Stored timestamps are the event's wall-clock interpreted as UTC (see
13	// docs/DECISIONS.md). For iCal we emit those digits with the event's TZID, so
14	// "1:00 PM" in the event's timezone round-trips correctly in calendar clients.
15	// "2026-10-08T13:00:00Z" -> "20261008T130000"
16	function localStamp(iso: string): string {
17	  return iso.slice(0, 19).replace(/[-:]/g, "");
18	}
19	
20	// A real UTC instant -> "YYYYMMDDTHHMMSSZ" (for DTSTAMP).
21	function utcStamp(date: Date): string {
22	  return `${date.toISOString().slice(0, 19).replace(/[-:]/g, "")}Z`;
23	}
24	
25	// RFC 5545 line folding at 75 octets (approximated by chars).
26	function fold(line: string): string {
27	  if (line.length <= 73) return line;
28	  const parts: string[] = [];
29	  for (let i = 0; i < line.length; i += 73) {
30	    parts.push((i === 0 ? "" : " ") + line.slice(i, i + 73));
31	  }
32	  return parts.join("\r\n");
33	}
34	
35	const RRULE: Record<string, string | null> = {
36	  none: null,
37	  daily: "FREQ=DAILY",
38	  weekly: "FREQ=WEEKLY",
39	  biweekly: "FREQ=WEEKLY;INTERVAL=2",
40	  monthly: "FREQ=MONTHLY",
41	};
42	
43	export function buildVEvent(
44	  event: EventRow,
45	  siteUrl: string,
46	  now: Date,
47	): string {
48	  const url = `${siteUrl}/events/${event.slug}`;
49	  const tz = event.timezone || "UTC";
50	  const description = [event.summary ?? event.description ?? "", url]
51	    .filter(Boolean)
52	    .join("\n\n");
53	  const rrule = RRULE[event.recurrence] ?? null;
54	  const until =
55	    rrule && event.recurrence_until
56	      ? `;UNTIL=${event.recurrence_until.replace(/-/g, "")}T235959Z`
57	      : "";
58	
59	  const lines = [
60	    "BEGIN:VEVENT",
61	    `UID:${event.id}@devsassemble.ai`,
62	    `DTSTAMP:${utcStamp(now)}`,
63	    `DTSTART;TZID=${tz}:${localStamp(event.starts_at)}`,
64	    ...(event.ends_at ? [`DTEND;TZID=${tz}:${localStamp(event.ends_at)}`] : []),
65	    ...(rrule ? [`RRULE:${rrule}${until}`] : []),
66	    `SUMMARY:${escapeText(event.title)}`,
67	    `DESCRIPTION:${escapeText(description)}`,
68	    `URL:${escapeText(url)}`,
69	    `LOCATION:${escapeText(
70	      event.location ?? (event.is_virtual ? "Virtual" : ""),
71	    )}`,
72	    `STATUS:${event.status === "cancelled" ? "CANCELLED" : "CONFIRMED"}`,
73	    "END:VEVENT",
74	  ];
75	  return lines.map(fold).join("\r\n");
76	}
77	
78	export function buildCalendar(
79	  events: EventRow[],
80	  siteUrl: string,
81	  now: Date,
82	): string {
83	  const header = [
84	    "BEGIN:VCALENDAR",
85	    "VERSION:2.0",
86	    "PRODID:-//DevsAssemble//Events//EN",
87	    "CALSCALE:GREGORIAN",
88	    "METHOD:PUBLISH",
89	    "X-WR-CALNAME:DevsAssemble Events",
90	    "X-WR-CALDESC:Upcoming DevsAssemble livestreams and meetups",
91	  ].join("\r\n");
92	
93	  const body = events.map((e) => buildVEvent(e, siteUrl, now)).join("\r\n");
94	
95	  return `${header}\r\n${body}\r\n${"END:VCALENDAR"}\r\n`;
96	}
