/** Tool categories — keep in sync with the tool_category enum (migration 0010). */
export const TOOL_CATEGORIES = [
  { value: "ai", label: "AI" },
  { value: "devops", label: "DevOps" },
  { value: "design", label: "Design" },
  { value: "productivity", label: "Productivity" },
  { value: "other", label: "Other" },
] as const;

export type ToolCategory = (typeof TOOL_CATEGORIES)[number]["value"];

export function isToolCategory(value: string): value is ToolCategory {
  return TOOL_CATEGORIES.some((c) => c.value === value);
}

export function toolCategoryLabel(value: string): string {
  return TOOL_CATEGORIES.find((c) => c.value === value)?.label ?? "Other";
}

import * as z from "zod";
import { TOOL_CATEGORIES } from "@/lib/tools/categories";

const CATEGORY_VALUES = TOOL_CATEGORIES.map((c) => c.value) as [
  string,
  ...string[],
];

export const toolSubmitSchema = z.object({
  name: z
    .string()
    .trim()
    .min(1, { error: "Give the tool a name." })
    .max(80, { error: "Keep the name under 80 characters." }),
  url: z.url({ error: "Paste the tool's URL (https://…)." }).max(500),
  category: z.enum(CATEGORY_VALUES, { error: "Pick a category." }),
  description: z
    .string()
    .trim()
    .max(500, { error: "Keep your note under 500 characters." })
    .optional()
    .or(z.literal("")),
});

import "server-only";

import { createClient } from "@/lib/supabase/server";
import type { ToolCategory } from "@/lib/tools/categories";

export type ToolSubmitter = {
  username: string | null;
  display_name: string | null;
  avatar_url: string | null;
} | null;

type ToolBase = {
  id: string;
  name: string;
  url: string;
  description: string | null;
  category: ToolCategory;
  submitted_by: string | null;
  created_at: string;
  submitter: ToolSubmitter;
};

export type ToolItem = ToolBase & {
  reactions: Record<string, number>;
  reactionCount: number;
  myReactions: string[];
};

const TOOL_SELECT =
  "id, name, url, description, category, submitted_by, created_at, submitter:profiles!tools_submitted_by_fkey ( username, display_name, avatar_url )";

export async function listTools(opts?: {
  sort?: "new" | "top";
  category?: ToolCategory;
}): Promise<ToolItem[]> {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  let query = supabase.from("tools").select(TOOL_SELECT);
  if (opts?.category) query = query.eq("category", opts.category);
  query = query.order("created_at", { ascending: false }).limit(100);

  const { data, error } = await query;
  if (error) throw error;

  const tools = (data ?? []) as unknown as ToolBase[];
  const ids = tools.map((t) => t.id);
  if (ids.length === 0) return [];

  const { data: reactionRows, error: rErr } = await supabase
    .from("tool_reactions")
    .select("tool_id, emoji, user_id")
    .in("tool_id", ids);
  if (rErr) throw rErr;

  const agg = new Map<
    string,
    { counts: Record<string, number>; mine: string[] }
  >();
  for (const id of ids) agg.set(id, { counts: {}, mine: [] });
  for (const row of (reactionRows ?? []) as {
    tool_id: string;
    emoji: string;
    user_id: string;
  }[]) {
    const entry = agg.get(row.tool_id);
    if (!entry) continue;
    entry.counts[row.emoji] = (entry.counts[row.emoji] ?? 0) + 1;
    if (user && row.user_id === user.id) entry.mine.push(row.emoji);
  }

  const result: ToolItem[] = tools.map((t) => {
    const entry = agg.get(t.id)!;
    const reactionCount = Object.values(entry.counts).reduce((a, b) => a + b, 0);
    return {
      ...t,
      reactions: entry.counts,
      reactionCount,
      myReactions: entry.mine,
    };
  });

  if (opts?.sort === "top") {
    result.sort(
      (a, b) =>
        b.reactionCount - a.reactionCount ||
        (a.created_at < b.created_at ? 1 : -1),
    );
  }
  return result;
}

"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { requireUser } from "@/lib/auth/dal";
import { toolSubmitSchema } from "@/lib/validation/tools";
import { isReactionEmoji } from "@/lib/repos/reactions";

export type ToolFormState = { error?: string };

/** Normalize a URL for dedup: lowercase host, drop hash, strip trailing slash. */
function normalizeUrl(raw: string): string | null {
  try {
    const u = new URL(raw.trim());
    if (u.protocol !== "http:" && u.protocol !== "https:") return null;
    u.hash = "";
    u.hostname = u.hostname.toLowerCase();
    let s = u.toString();
    s = s.replace(/\/+$/, "");
    return s;
  } catch {
    return null;
  }
}

export async function submitTool(
  _prev: ToolFormState,
  formData: FormData,
): Promise<ToolFormState> {
  const user = await requireUser();

  const parsed = toolSubmitSchema.safeParse({
    name: formData.get("name"),
    url: formData.get("url"),
    category: formData.get("category"),
    description: formData.get("description"),
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Check the form." };
  }

  const url = normalizeUrl(parsed.data.url);
  if (!url) return { error: "That doesn't look like a valid https URL." };

  const supabase = await createClient();
  const { error } = await supabase.from("tools").insert({
    name: parsed.data.name,
    url,
    category: parsed.data.category,
    description:
      parsed.data.description && parsed.data.description !== ""
        ? parsed.data.description
        : null,
    submitted_by: user.id,
  });

  if (error) {
    if (error.code === "23505")
      return { error: "That tool's already on the shelf." };
    return { error: error.message };
  }

  revalidatePath("/tools");
  redirect("/tools");
}

/** Toggle one emoji reaction for the current user on a tool. */
export async function toggleToolReaction(formData: FormData): Promise<void> {
  const user = await requireUser();
  const toolId = String(formData.get("tool_id") ?? "");
  const emoji = String(formData.get("emoji") ?? "");
  if (!toolId || !isReactionEmoji(emoji)) return;

  const supabase = await createClient();
  const { data: existing } = await supabase
    .from("tool_reactions")
    .select("tool_id")
    .eq("tool_id", toolId)
    .eq("user_id", user.id)
    .eq("emoji", emoji)
    .maybeSingle();

  if (existing) {
    await supabase
      .from("tool_reactions")
      .delete()
      .eq("tool_id", toolId)
      .eq("user_id", user.id)
      .eq("emoji", emoji);
  } else {
    await supabase
      .from("tool_reactions")
      .insert({ tool_id: toolId, user_id: user.id, emoji });
  }

  revalidatePath("/tools");
}

"use client";

import { toggleToolReaction } from "@/lib/tools/actions";
import { REACTION_EMOJIS } from "@/lib/repos/reactions";

const chip =
  "focus-comic inline-flex items-center gap-1 rounded-full border-[2px] border-brand-ink px-3 py-1 text-sm shadow-comic-sm transition-transform hover:-translate-y-0.5";

export function ToolReactionBar({
  toolId,
  reactions,
  myReactions,
  isAuthed,
  loginHref,
}: {
  toolId: string;
  reactions: Record<string, number>;
  myReactions: string[];
  isAuthed: boolean;
  loginHref: string;
}) {
  if (!isAuthed) {
    return (
      <div className="flex flex-wrap gap-2">
        {REACTION_EMOJIS.map((e) => (
          <a
            key={e}
            href={loginHref}
            title="Sign in to react"
            className={`${chip} bg-surface text-brand-ink`}
          >
            <span aria-hidden>{e}</span>
            {reactions[e] ? (
              <span className="font-mono text-xs">{reactions[e]}</span>
            ) : null}
          </a>
        ))}
      </div>
    );
  }

  return (
    <div className="flex flex-wrap gap-2">
      {REACTION_EMOJIS.map((e) => {
        const active = myReactions.includes(e);
        const count = reactions[e] ?? 0;
        return (
          <form key={e} action={toggleToolReaction}>
            <input type="hidden" name="tool_id" value={toolId} />
            <input type="hidden" name="emoji" value={e} />
            <button
              type="submit"
              aria-pressed={active}
              className={`${chip} ${active ? "bg-brand-lime text-brand-ink" : "bg-surface text-brand-ink"}`}
            >
              <span aria-hidden>{e}</span>
              {count > 0 && <span className="font-mono text-xs">{count}</span>}
            </button>
          </form>
        );
      })}
    </div>
  );
}

